#include "ksPeriodicTask.h"
#include <stdexcept>
#include <iostream>
#include <vector>
int main(){using T=ks::PeriodicTask;using S=T::Stage;unsigned cases=0;for(unsigned kind=0;kind<4;++kind)for(unsigned mode=0;mode<256;++mode)for(unsigned value=0;value<256;++value){T t(static_cast<T::Kind>(kind));unsigned pending=value;std::vector<unsigned>reads,writes;unsigned child=0;bool eligible=kind&&mode==kind-1&&(kind!=2||pending);while(t.stage()!=S::Complete){if(t.child()!=T::Child::None){if(!eligible||unsigned(t.child())!=child+1)throw std::runtime_error("child order");unsigned input=child<3?uint8_t(value+child*37):child==3?value:value>>3;unsigned secondary=child==4?uint8_t(value^0xaa)>>2:uint8_t(value^0xaa);if(t.input()!=input||(child>=3&&t.secondary()!=secondary))throw std::runtime_error("child parameters");++child;if(!t.resumeChild())throw std::runtime_error("resume");continue;}auto cost=t.nextClocks();if(t.advanceBefore(cost-1,[](unsigned)->unsigned{throw std::runtime_error("early read");},[](uint8_t){throw std::runtime_error("early write");}))throw std::runtime_error("early");t.advanceBefore(cost,[&](unsigned field){reads.push_back(field);return field==T::TriggerField?pending:field==249?mode:field>=219&&field<=221?unsigned(uint8_t(value+(field-219)*37)):field==79?value:unsigned(uint8_t(value^0xaa));},[&](uint8_t byte){writes.push_back(byte);});}std::vector<unsigned>expected;if(kind==2)expected.push_back(T::TriggerField);if(kind!=2||pending)expected.push_back(249);if(eligible)for(unsigned field:{219u,220u,221u,79u,78u,79u,78u})expected.push_back(field);std::vector<unsigned>ew;if(kind==0&&mode==1)ew.push_back(1);if(kind==2&&pending)ew.push_back(0);if(reads!=expected||writes!=ew||child!=(eligible?5u:0u))throw std::runtime_error("routing/admission/field order");++cases;}std::cout<<"PASS: "<<cases<<" pure periodic properties\n";}
